// Package cron parses cron expressions and projects future run times.
package cron

import (
	"fmt"
	"strings"
	"time"
)

// Schedule is a parsed cron expression. Each field is a bitmask of the values
// that field accepts.
type Schedule struct {
	minute uint64 // 0-59
	hour   uint64 // 0-23
	dom    uint64 // 1-31
	month  uint64 // 1-12
	dow    uint64 // 0-6, Sunday is 0
}

type fieldSpec struct {
	name string
	min  int
	max  int
}

var fields = []fieldSpec{
	{"minute", 0, 59},
	{"hour", 0, 23},
	{"day-of-month", 1, 31},
	{"month", 1, 12},
	{"day-of-week", 0, 6},
}

// Parse turns a five-field cron expression into a Schedule.
func Parse(expr string) (*Schedule, error) {
	parts := strings.Fields(expr)
	if len(parts) != len(fields) {
		return nil, fmt.Errorf("expression has %d fields, want %d (minute hour day-of-month month day-of-week)", len(parts), len(fields))
	}
	var masks [5]uint64
	for i, p := range parts {
		m, err := parseField(p, fields[i])
		if err != nil {
			return nil, err
		}
		masks[i] = m
	}
	return &Schedule{masks[0], masks[1], masks[2], masks[3], masks[4]}, nil
}

func parseField(s string, f fieldSpec) (uint64, error) {
	if s == "*" {
		return maskRange(f.min, f.max, 1), nil
	}
	return 0, fmt.Errorf("%s field: cannot parse %q", f.name, s)
}

func maskRange(lo, hi, step int) uint64 {
	var m uint64
	for v := lo; v <= hi; v += step {
		m |= 1 << uint(v)
	}
	return m
}

// Match reports whether the schedule would run at t (to the minute).
func (s *Schedule) Match(t time.Time) bool {
	return s.minute&(1<<uint(t.Minute())) != 0 &&
		s.hour&(1<<uint(t.Hour())) != 0 &&
		s.month&(1<<uint(int(t.Month()))) != 0 &&
		s.dayMatch(t)
}

func (s *Schedule) dayMatch(t time.Time) bool {
	return s.dom&(1<<uint(t.Day())) != 0 && s.dow&(1<<uint(int(t.Weekday()))) != 0
}
EOF
