func TestDayOfMonthOrDayOfWeek(t *testing.T) {
	// Both day fields restricted: either one matching is enough.
	s, err := Parse("0 0 13 * FRI")
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	// 2024-09-13 is a Friday the 13th: both match.
	if !s.Match(time.Date(2024, 9, 13, 0, 0, 0, 0, time.UTC)) {
