	if !s.Match(time.Date(2024, 10, 13, 0, 0, 0, 0, time.UTC)) {
		t.Error("want match on the 13th even though it is not a Friday")
	}
	// 2024-09-20 is a Friday: day-of-week alone matches.
	if !s.Match(time.Date(2024, 9, 20, 0, 0, 0, 0, time.UTC)) {
		t.Error("want match on a Friday even though it is not the 13th")
	}
	// 2024-09-19 is a Thursday: neither matches.
	if s.Match(time.Date(2024, 9, 19, 0, 0, 0, 0, time.UTC)) {
		t.Error("want no match on Thu 19 Sep")
	}

	// Only day-of-month restricted: day-of-week must not widen it.
	dom, err := Parse("0 0 13 * *")
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	if dom.Match(time.Date(2024, 9, 20, 0, 0, 0, 0, time.UTC)) {
		t.Error("`13 * *` should not match the 20th")
	}

	// Only day-of-week restricted: day-of-month must not widen it.
	dow, err := Parse("0 0 * * FRI")
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	if dow.Match(time.Date(2024, 9, 19, 0, 0, 0, 0, time.UTC)) {
		t.Error("`* * FRI` should not match a Thursday")
	}
}
