// into an instant, so a schedule still fires on a day whose local clock skips
// the hour it names. Because the result is always strictly after from,
// stepping a sequence with Next cannot repeat an instant across a
// daylight-saving fall-back either.
func (s *Schedule) Next(from time.Time) time.Time {
	loc := from.Location()
	// cursor is a bare calendar cursor, held in UTC so that adding a minute
	// never changes the wall-clock fields by anything but a minute.
	cursor := time.Date(from.Year(), from.Month(), from.Day(), from.Hour(), from.Minute()+1, 0, 0, time.UTC)
	deadline := cursor.Add(horizon)

	for cursor.Before(deadline) {
		if !s.dateMatch(cursor) {
			cursor = nextMidnight(cursor)
			continue
		}
		if !s.timeMatch(cursor) {
			cursor = cursor.Add(time.Minute)
			continue
		}
		candidate := time.Date(cursor.Year(), cursor.Month(), cursor.Day(), cursor.Hour(), cursor.Minute(), 0, 0, loc)
		if candidate.After(from) {
			return candidate
		}
		cursor = cursor.Add(time.Minute)
	}
	return time.Time{}
}

func nextMidnight(t time.Time) time.Time {
	return time.Date(t.Year(), t.Month(), t.Day()+1, 0, 0, 0, 0, time.UTC)
}

func (s *Schedule) dateMatch(t time.Time) bool {
	return s.month&(1<<uint(int(t.Month()))) != 0 && s.dayMatch(t)
}

func (s *Schedule) timeMatch(t time.Time) bool {
	return s.minute&(1<<uint(t.Minute())) != 0 && s.hour&(1<<uint(t.Hour())) != 0
}
