package cron

import (
	"fmt"
	"strings"
)

var monthWords = []string{"January", "February", "March", "April", "May", "June",
	"July", "August", "September", "October", "November", "December"}

var dayWords = []string{"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"}

// Describe renders the schedule as one plain-English line.
func (s *Schedule) Describe() string {
	clauses := []string{s.timeClause()}
	if days := s.dayClauses(); len(days) > 0 {
		clauses = append(clauses, days...)
	} else if !strings.HasPrefix(clauses[0], "every") {
		clauses = append(clauses, "every day")
	}
	return strings.Join(clauses, ", ")
}

func (s *Schedule) timeClause() string {
	minuteAll := s.minute == maskRange(0, 59, 1)
	hourAll := s.hour == maskRange(0, 23, 1)

	if hourAll {
		if minuteAll {
			return "every minute"
		}
		if n, ok := uniformStep(s.minute, 0, 59); ok {
			return fmt.Sprintf("every %d minutes", n)
		}
	}
	mins, hours := setBits(s.minute), setBits(s.hour)
	if len(mins) == 1 && len(hours) == 1 {
		return fmt.Sprintf("at %02d:%02d", hours[0], mins[0])
	}
	minPart := "minute " + list(mins, nil)
	if minuteAll {
		minPart = "every minute"
	}
	hourPart := "hours " + list(hours, nil)
	if hourAll {
		hourPart = "every hour"
	} else if len(hours) == 1 {
		hourPart = "hour " + list(hours, nil)
	}
	return fmt.Sprintf("at %s of %s", minPart, hourPart)
}

// dayClauses renders the day-of-month, day-of-week and month restrictions.
// Only restricted fields appear, so an unrestricted schedule yields nothing.
func (s *Schedule) dayClauses() []string {
	var out []string
	switch {
	case s.domRestricted && s.dowRestricted:
		out = append(out, fmt.Sprintf("on day %s of the month or on %s",
			list(setBits(s.dom), nil), list(setBits(s.dow), dayWords)))
	case s.domRestricted:
		out = append(out, "on day "+list(setBits(s.dom), nil)+" of the month")
	case s.dowRestricted:
		out = append(out, "on "+list(setBits(s.dow), dayWords))
	}
	if s.month != maskRange(1, 12, 1) {
		out = append(out, "in "+list(setBits(s.month), monthWords))
	}
	return out
}

// list renders a set of values, collapsing runs into ranges. When words is
// non-nil the values index into it: words[0] is the value f.min.
func list(vals []int, words []string) string {
	name := func(v int) string {
		if words == nil {
			return fmt.Sprint(v)
		}
		return words[v-offsetOf(words)]
	}
	var parts []string
	for i := 0; i < len(vals); {
		j := i
		for j+1 < len(vals) && vals[j+1] == vals[j]+1 {
			j++
		}
		switch {
		case j-i >= 1:
			parts = append(parts, name(vals[i])+"-"+name(vals[j]))
		default:
			parts = append(parts, name(vals[i]))
		}
		i = j + 1
	}
	return strings.Join(parts, ",")
}

// offsetOf reports the value that words[0] stands for: months start at 1,
// weekdays at 0.
func offsetOf(words []string) int {
	if len(words) == 12 {
		return 1
	}
	return 0
}

func setBits(m uint64) []int {
	var out []int
	for v := 0; v < 64; v++ {
		if m&(1<<uint(v)) != 0 {
			out = append(out, v)
		}
	}
	return out
}

// uniformStep reports the step n when the mask is exactly min, min+n, min+2n...
// across the whole field, as `*/n` produces.
func uniformStep(m uint64, min, max int) (int, bool) {
	vals := setBits(m)
	if len(vals) < 2 || vals[0] != min {
		return 0, false
	}
	n := vals[1] - vals[0]
	return n, m == maskRange(min, max, n)
}
