package cron

import (
	"flag"
	"fmt"
	"io"
	"time"
)

// Exit codes. `match` uses exitNoMatch to say "would not run", so errors take a
// code of their own.
const (
	exitOK      = 0
	exitNoMatch = 1
	exitError   = 2
)

const usage = `usage:
  cron next <expr> --count N [--from <ISO8601>] [--tz <zone>]   the next N run times
  cron describe <expr>                                          one plain-English line
  cron match <expr> <ISO8601>                                   exit 0 if it would run
`

// Run executes one command line and returns the process exit code.
func Run(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		fmt.Fprint(stderr, usage)
		return exitError
	}
	switch args[0] {
	case "next":
		return runNext(args[1:], stdout, stderr)
	default:
		fmt.Fprintf(stderr, "unknown command %q\n%s", args[0], usage)
		return exitError
	}
}

func runNext(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("next", flag.ContinueOnError)
	fs.SetOutput(stderr)
	count := fs.Int("count", 1, "how many run times to print")
	from := fs.String("from", "", "start from this ISO 8601 time (default: now)")
	zone := fs.String("tz", "UTC", "compute run times in this zone")
	expr, err := parseArgs(fs, args, 1)
	if err != nil {
		fmt.Fprintf(stderr, "%v\n", err)
		return exitError
	}

	s, err := Parse(expr[0])
	if err != nil {
		fmt.Fprintf(stderr, "%v\n", err)
		return exitError
	}
	loc, err := time.LoadLocation(*zone)
	if err != nil {
		fmt.Fprintf(stderr, "unknown zone %q\n", *zone)
		return exitError
	}
	start, err := parseTime(*from, loc)
	if err != nil {
		fmt.Fprintf(stderr, "%v\n", err)
		return exitError
	}

	for i := 0; i < *count; i++ {
		start = s.Next(start)
		if start.IsZero() {
			fmt.Fprintf(stderr, "%q has no further run times\n", expr[0])
			return exitError
		}
		fmt.Fprintln(stdout, start.Format(time.RFC3339))
	}
	return exitOK
}

// parseArgs parses flags that may appear before or after the positional
// arguments, and checks that exactly want of them are present.
func parseArgs(fs *flag.FlagSet, args []string, want int) ([]string, error) {
	var positional []string
	for {
		if err := fs.Parse(args); err != nil {
			return nil, err
		}
		rest := fs.Args()
		if len(rest) == 0 {
			break
		}
		positional = append(positional, rest[0])
		args = rest[1:]
	}
	if len(positional) != want {
		return nil, fmt.Errorf("%s takes %d argument(s), got %d", fs.Name(), want, len(positional))
	}
	return positional, nil
}

func parseTime(s string, loc *time.Location) (time.Time, error) {
	if s == "" {
		return time.Now().In(loc), nil
	}
	if t, err := time.Parse(time.RFC3339, s); err == nil {
		return t.In(loc), nil
	}
	// No offset given: read the time as local to the chosen zone.
	for _, layout := range []string{"2006-01-02T15:04:05", "2006-01-02T15:04", "2006-01-02"} {
		if t, err := time.ParseInLocation(layout, s, loc); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("cannot parse time %q, want ISO 8601 such as 2024-03-17T04:30:00Z", s)
}
